#!/usr/bin/env node
/**
 * build-province-frames.mjs - the ground of every 省级市场, from the table.
 *
 * WHAT IT WRITES: portals/app/app/domains/shared/province-frames.ts - for each
 * provincial-level division that has anything below it, the units a region
 * is made of when that province is the whole market: its prefecture-level
 * cities, or for the four municipalities its districts and counties, since a
 * municipality has no cities under it.
 *
 * WHY A GENERATED FILE AND NOT A QUERY. The Prisma store reads these rows from
 * yucer_ref.admin_division directly; the in-memory store the demo runs on has
 * no table to read, and market-division.ts branches on the list (the by-city
 * carve is derived from it). admin-division.db.test.ts proves the file and the
 * table agree, so a re-run of incr/0038 is followed by a re-run of this.
 *
 *   DATABASE_URL=postgres://... node scripts/data/build-province-frames.mjs
 *
 * Owner, 2026-09-09: 你把全国的都加上吧 … 我们的行政区划数据应该先预置完整.
 */
import { writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const HERE = dirname(fileURLToPath(import.meta.url));
const APP = join(HERE, "..", "..", "portals", "app");
const OUT = join(APP, "app", "domains", "shared", "province-frames.ts");
const { Client } = createRequire(join(APP, "package.json"))("pg");

/** GB/T 2260's filing row XX9000 省直辖县级行政区划 is a convention, not a
 *  place a region holds. (A municipality's 市辖区 / 县 rows are filing rows
 *  too, but a municipality's ground is read one level down and never sees
 *  them - and XX0100 is 西安 in every real province, so no pattern may say
 *  otherwise. Caught 2026-09-09: the first cut dropped two cities from each
 *  of the 27 provinces, and the db test that compares file to table filtered
 *  both through the same helper and passed.) */
const PSEUDO = /^\d{2}9000$/;
/** 北京 天津 上海 重庆 - no prefecture-level cities; the ground is one level down. */
const MUNICIPALITIES = new Set(["110000", "120000", "310000", "500000"]);

const url = process.env.DATABASE_URL;
if (!url) {
  console.error("DATABASE_URL is required");
  process.exit(2);
}
const c = new Client({ connectionString: url });
await c.connect();
const provinces = (
  await c.query(
    `SELECT p.id, p.code, p.abbr_en, p.name_zh, p.path FROM yucer_ref.admin_division p
      WHERE p.level = 3 AND p.status = 'active'
        AND EXISTS (SELECT 1 FROM yucer_ref.admin_division x WHERE x.parent_id = p.id)
      ORDER BY p.sort_order`,
  )
).rows;
const frames = [];
for (const p of provinces) {
  const municipality = MUNICIPALITIES.has(p.code);
  const units = municipality
    ? (
        await c.query(
          `SELECT code, name_zh, short_zh FROM yucer_ref.admin_division
            WHERE level = 5 AND status = 'active' AND path LIKE $1 ORDER BY sort_order`,
          [`${p.path}/%`],
        )
      ).rows
    : (
        await c.query(
          `SELECT code, name_zh, short_zh FROM yucer_ref.admin_division
            WHERE level = 4 AND status = 'active' AND parent_id = $1 ORDER BY sort_order`,
          [p.id],
        )
      ).rows.filter((r) => !PSEUDO.test(r.code));
  frames.push({
    code: p.abbr_en,
    province: p.name_zh,
    adcode: p.code,
    unit: municipality ? "district" : "city",
    units: units.map((u) => ({ code: u.code, name: u.name_zh, short: u.short_zh })),
  });
}
await c.end();

const lines = [];
lines.push("/* GENERATED by scripts/data/build-province-frames.mjs from yucer_ref.admin_division");
lines.push(` * (incr/0038). Do not hand-edit: ${frames.length} provincial-level divisions,`);
lines.push(` * ${frames.reduce((n, f) => n + f.units.length, 0)} units. Re-run the generator to change it.`);
lines.push(" *");
lines.push(" * The ground of every 省级市场: the units a region is made of when one province");
lines.push(" * is the whole market - prefecture-level cities, or a municipality's districts");
lines.push(" * and counties. admin-division.db.test.ts proves this file against the table.");
lines.push(" */");
lines.push("");
lines.push("export interface ProvinceGround {");
lines.push("  /** The two GB/T 2260 letters market_scope.scope_province stores. */");
lines.push("  readonly code: string;");
lines.push("  readonly province: string;");
lines.push("  /** The province's six-digit adcode - the root of its units' paths. */");
lines.push("  readonly adcode: string;");
lines.push("  /** What a region is made of here: 市 for a province, 区 for a municipality. */");
lines.push('  readonly unit: "city" | "district";');
lines.push("  /** In GB/T 2260 order: 六位码 / 全称 / 简称. */");
lines.push("  readonly units: readonly { readonly code: string; readonly name: string; readonly short: string }[];");
lines.push("}");
lines.push("");
lines.push("export const PROVINCE_GROUNDS: readonly ProvinceGround[] = [");
for (const f of frames) {
  lines.push(`  { code: ${JSON.stringify(f.code)}, province: ${JSON.stringify(f.province)}, adcode: ${JSON.stringify(f.adcode)}, unit: ${JSON.stringify(f.unit)}, units: [`);
  for (const u of f.units) {
    lines.push(`    { code: ${JSON.stringify(u.code)}, name: ${JSON.stringify(u.name)}, short: ${JSON.stringify(u.short)} },`);
  }
  lines.push("  ] },");
}
lines.push("];");
lines.push("");
writeFileSync(OUT, lines.join("\n"));
console.log(`[province-frames] wrote ${frames.length} provinces, ${frames.reduce((n, f) => n + f.units.length, 0)} units -> ${OUT}`);
